import json, random, collections
TOPICS=['algebra','geometry','combinatorics','number_theory']
def load():
    data={}
    for t in TOPICS:
        qs=[]
        for f in [f'/tmp/dev_{t}.json', f'/tmp/dev2_{t}.json']:
            qs+=json.load(open(f))['questions']
        data[t]=qs
    return data

class Env:
    def __init__(self, qs, budget_per=6, seed=0):
        self.rng=random.Random(seed)
        self.qs=qs
        self.questions=[{"id":q['id'],"topic":q['topic']} for q in qs]
        self.budget=budget_per*len(qs)
        self.used=0
        self.n_variants=5
        self.topics=TOPICS
        self.pools={}
        for q in qs:
            byv=collections.defaultdict(list)
            for s in q['samples']: byv[s['variant']].append((s['answer'],s['score']))
            for v in byv: self.rng.shuffle(byv[v])
            self.pools[q['id']]=byv
        self.truth={q['id']:q['correct_answer'] for q in qs}
        self.submitted=None
    def left(self): return self.budget-self.used
    def sample(self, qid, variant=0):
        if self.used>=self.budget: raise RuntimeError("pool empty")
        self.used+=1
        p=self.pools[qid][variant]
        if not p: raise RuntimeError("sim pool exhausted for %s v%d"%(qid,variant))
        return p.pop()
    def submit(self, out):
        self.submitted=out
    def score(self):
        acc=collections.defaultdict(list)
        for q in self.questions:
            acc[q['topic']].append(self.submitted.get(q['id'])==self.truth[q['id']])
        res={t:sum(v)/len(v) for t,v in acc.items()}
        res['all']=sum(sum(v) for v in acc.values())/len(self.questions)
        res['used']=self.used
        return res

def run_policy(policy_run, data, reps=5, n_per_topic=60, seed=0):
    tot=collections.defaultdict(float)
    for r in range(reps):
        rng=random.Random(seed+r)
        qs=[]
        for t in TOPICS:
            qs+=rng.sample(data[t], n_per_topic)
        rng.shuffle(qs)
        env=Env(qs, seed=seed+r)
        policy_run(env)
        for k,v in env.score().items(): tot[k]+=v/reps
    return dict(tot)
